import { amount, money, calculate } from './settlement-core.js';

const key='lunch-settlement-v2';
const $=selector=>document.querySelector(selector);
const escapeHtml=value=>String(value ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const newId=()=>crypto.randomUUID();
const blankGroup=()=>({id:newId(),title:'점심',place:'',payerId:'',personal:[],shared:[]});
function load(){try{const parsed=JSON.parse(localStorage.getItem(key));if(parsed?.version===2&&Array.isArray(parsed.participants)&&Array.isArray(parsed.groups))return parsed}catch{}return{version:2,participants:[],groups:[blankGroup()]}}
let state=load();
function save(){try{localStorage.setItem(key,JSON.stringify(state))}catch{showToast('저장 공간이 부족해요. 내용을 복사해 보관해 주세요.')}}
const personName=id=>state.participants.find(p=>p.id===id)?.name||'참여자 미선택';
const groupById=id=>state.groups.find(g=>g.id===id);
function fieldOptions(selected,placeholder='참여자 선택'){return `<option value="">${placeholder}</option>`+state.participants.map(p=>`<option value="${p.id}" ${p.id===selected?'selected':''}>${escapeHtml(p.name)}</option>`).join('')}
function renderPeople(){ $('#settlePeople').innerHTML=state.participants.length?state.participants.map(p=>`<span class="settle-person">${escapeHtml(p.name)}<button type="button" data-action="remove-person" data-person="${p.id}" aria-label="${escapeHtml(p.name)} 삭제">×</button></span>`).join(''):'<span class="settle-empty">먼저 함께 먹은 사람을 등록해 주세요.</span>'; }
function personalRow(group,item){return `<div class="settle-row" data-group="${group.id}" data-kind="personal" data-item="${item.id}"><select aria-label="먹은 사람" data-field="participantId">${fieldOptions(item.participantId)}</select><input data-field="name" aria-label="개인 메뉴명" maxlength="60" placeholder="메뉴명" value="${escapeHtml(item.name)}"><input data-field="amount" aria-label="개인 메뉴 금액" inputmode="numeric" placeholder="0원" value="${item.amount?money(item.amount):''}"><button type="button" class="settle-delete settle-danger" data-action="remove-item" aria-label="개인 메뉴 삭제">×</button></div>`}
function sharedRow(group,item){const ids=item.participantIds||[];return `<div data-group="${group.id}" data-kind="shared" data-item="${item.id}"><div class="settle-row shared"><input data-field="name" aria-label="공용 메뉴명" maxlength="60" placeholder="공용 메뉴명" value="${escapeHtml(item.name)}"><input data-field="amount" aria-label="공용 메뉴 금액" inputmode="numeric" placeholder="0원" value="${item.amount?money(item.amount):''}"><button type="button" class="settle-delete settle-danger" data-action="remove-item" aria-label="공용 메뉴 삭제">×</button></div><div class="settle-checks">${state.participants.map(p=>`<label><input type="checkbox" data-field="participantIds" value="${p.id}" ${ids.includes(p.id)?'checked':''}>${escapeHtml(p.name)}</label>`).join('')||'<span class="settle-empty">참여자를 먼저 등록해 주세요.</span>'}</div><div class="settle-line-note" data-split="${item.id}"></div></div>`}
function renderGroups(){const calc=calculate(state);$('#settleGroups').innerHTML=state.groups.map((g,index)=>`<section class="settle-section" data-group="${g.id}"><div class="settle-group-head"><h3>${index+1}차 정산 묶음</h3><button type="button" class="settle-danger" data-action="remove-group">묶음 삭제</button></div><div class="settle-fields"><div><label class="settle-label">묶음 이름</label><input data-group-field="title" maxlength="40" value="${escapeHtml(g.title)}" placeholder="예: 점심"></div><div><label class="settle-label">결제자</label><select data-group-field="payerId">${fieldOptions(g.payerId,'결제자 선택')}</select></div></div><label class="settle-label" style="margin-top:13px">식당·카페 이름</label><div class="settle-place"><input data-group-field="place" maxlength="80" value="${escapeHtml(g.place)}" placeholder="예: 북창동순두부"><a class="settle-map settle-light" href="${g.place?'https://map.naver.com/p/search/'+encodeURIComponent(g.place+' 서울'):'#'}" target="_blank" rel="noopener" data-map="${g.id}" ${g.place?'':'aria-disabled="true"'}>네이버지도에서 보기 ↗</a></div><div class="settle-list-title">개인 메뉴</div>${g.personal.map(i=>personalRow(g,i)).join('')}<button type="button" class="settle-light" data-action="add-personal">+ 개인 메뉴 추가</button><div class="settle-list-title">공용 메뉴</div>${g.shared.map(i=>sharedRow(g,i)).join('')}<button type="button" class="settle-light" data-action="add-shared">+ 공용 메뉴 추가</button><div class="settle-group-total">묶음 합계 ${money(calc.groups[index].total)}</div></section>`).join('');updateSplits()}
function updateSplits(){for(const group of state.groups)for(const item of group.shared){const el=document.querySelector(`[data-split="${item.id}"]`);if(!el)continue;const ids=state.participants.filter(p=>(item.participantIds||[]).includes(p.id));if(!ids.length){el.textContent=item.amount?'먹은 사람을 선택해 주세요.':'';continue}const base=Math.floor(amount(item.amount)/ids.length),remainder=amount(item.amount)%ids.length;el.textContent=`${ids.length}명 배분 · ${remainder?`${money(base)}~${money(base+1)} (남은 ${remainder}원은 앞 순서부터 1원씩)`: `각 ${money(base)}`}`}}
function renderResults(){const c=calculate(state);$('#settleGrandTotal').textContent=money(c.grandTotal);$('#settleGroupCount').textContent=`${state.groups.length}개 묶음 · ${state.participants.length}명`;
  $('#settleWarnings').innerHTML=c.errors.map(x=>`<p class="settle-warning">${escapeHtml(x)}</p>`).join('');
  $('#settleCards').innerHTML=c.people.length?c.people.map(p=>`<div class="settle-card"><h4>${escapeHtml(p.name)}</h4><div class="line"><span>개인 메뉴</span><b>${money(p.personal)}</b></div><div class="line"><span>공용 메뉴</span><b>${money(p.shared)}</b></div><div class="line"><span>본인 부담액</span><b>${money(p.owed)}</b></div><div class="line"><span>결제한 금액</span><b>${money(p.paid)}</b></div><div class="line"><span>${p.net>=0?'받을 금액':'보낼 금액'}</span><b>${money(Math.abs(p.net))}</b></div></div>`).join(''):'<p class="settle-empty">참여자를 등록하면 사람별 결과가 나와요.</p>';
  $('#settleTransfers').innerHTML=c.errors.length?'<p class="settle-empty">입력 내용을 확인하면 송금 결과가 나와요.</p>':c.transfers.length?c.transfers.map(t=>`<div class="settle-transfer">${escapeHtml(personName(t.from))} → ${escapeHtml(personName(t.to))} ${money(t.amount)}</div>`).join(''):'<p class="settle-empty">송금할 금액이 없어요.</p>';
  for(const group of c.groups){const box=document.querySelector(`#settleGroups [data-group="${group.id}"] > .settle-group-total`);if(box)box.textContent=`묶음 합계 ${money(group.total)}`}updateSplits(); }
function renderAll(){renderPeople();renderGroups();renderResults()}
function addPerson(){const input=$('#settleNewPerson'),name=input.value.trim();if(!name){showToast('이름을 입력해 주세요.');return}if(state.participants.some(p=>p.name===name)){showToast('이미 등록된 이름이에요.');return}state.participants.push({id:newId(),name:name.slice(0,30)});input.value='';save();renderAll();input.focus()}
$('#settleAddPerson').onclick=addPerson;$('#settleNewPerson').onkeydown=e=>{if(e.key==='Enter')addPerson()};
$('#settleAddGroup').onclick=()=>{const group=blankGroup();group.title=state.groups.length===0?'점심':`${state.groups.length+1}차`;state.groups.push(group);save();renderAll();document.querySelector(`[data-group="${group.id}"]`)?.scrollIntoView({behavior:'smooth',block:'start'})};
$('#settlePeople').onclick=e=>{const b=e.target.closest('[data-action="remove-person"]');if(!b)return;const id=b.dataset.person;state.participants=state.participants.filter(p=>p.id!==id);for(const g of state.groups){g.personal=g.personal.filter(i=>i.participantId!==id);g.shared.forEach(i=>i.participantIds=i.participantIds.filter(x=>x!==id));if(g.payerId===id)g.payerId=''}save();renderAll();showToast('참여자와 해당 개인 메뉴를 삭제했어요.')};
$('#settleGroups').onclick=e=>{const b=e.target.closest('[data-action]');if(!b)return;const section=b.closest('section[data-group]'),group=groupById(section?.dataset.group);if(!group)return;const action=b.dataset.action;
  if(action==='remove-group'){state.groups=state.groups.filter(g=>g.id!==group.id);if(!state.groups.length)state.groups.push(blankGroup())}
  if(action==='add-personal')group.personal.push({id:newId(),participantId:'',name:'',amount:0});
  if(action==='add-shared')group.shared.push({id:newId(),name:'',amount:0,participantIds:[]});
  if(action==='remove-item'){const wrapper=b.closest('[data-item]'),list=wrapper.dataset.kind==='shared'?'shared':'personal';group[list]=group[list].filter(i=>i.id!==wrapper.dataset.item)}
  save();renderAll();};
$('#settleGroups').oninput=e=>{const target=e.target,section=target.closest('section[data-group]'),group=groupById(section?.dataset.group);if(!group)return;if(target.dataset.groupField){group[target.dataset.groupField]=target.value;if(target.dataset.groupField==='place'){const link=section.querySelector('[data-map]');link.href=target.value.trim()?'https://map.naver.com/p/search/'+encodeURIComponent(target.value.trim()+' 서울'):'#';link.setAttribute('aria-disabled',target.value.trim()?'false':'true')}}else{const wrapper=target.closest('[data-item]');if(!wrapper)return;const item=group[wrapper.dataset.kind].find(i=>i.id===wrapper.dataset.item);if(!item)return;if(target.dataset.field==='amount'){const before=target.value.slice(0,target.selectionStart??target.value.length).replace(/[^0-9]/g,'').length;item.amount=amount(target.value);const formatted=item.amount?money(item.amount):'';target.value=formatted;let pos=0,count=0;while(pos<formatted.length&&count<before){if(/[0-9]/.test(formatted[pos]))count++;pos++}target.setSelectionRange(pos,pos)}else if(target.dataset.field==='name')item.name=target.value}save();renderResults()};
$('#settleGroups').onchange=e=>{const target=e.target,section=target.closest('section[data-group]'),group=groupById(section?.dataset.group);if(!group)return;if(target.dataset.groupField){group[target.dataset.groupField]=target.value}else{const wrapper=target.closest('[data-item]');if(!wrapper)return;const item=group[wrapper.dataset.kind].find(i=>i.id===wrapper.dataset.item);if(!item)return;if(target.dataset.field==='participantId')item.participantId=target.value;if(target.dataset.field==='participantIds')item.participantIds=[...wrapper.querySelectorAll('input[data-field="participantIds"]:checked')].map(x=>x.value)}save();renderResults()};
$('#settleGroups').onfocusout=e=>{if(e.target.dataset.field==='amount')e.target.value=e.target.value?money(amount(e.target.value)):''};
$('#settleGroups').addEventListener('click',e=>{const link=e.target.closest('[data-map]');if(link?.getAttribute('aria-disabled')==='true'){e.preventDefault();showToast('식당·카페 이름을 먼저 입력해 주세요.')}});
function shareText(){const c=calculate(state),lines=['[점심 정산]',...c.groups.map(g=>`${g.title||'정산 묶음'} · ${money(g.total)} · 결제자 ${personName(g.payerId)}`),`전체 ${money(c.grandTotal)}`,...c.people.map(p=>`${p.name}: 개인 ${money(p.personal)} + 공용 ${money(p.shared)} = 본인 부담 ${money(p.owed)}`),'[송금]'];return lines.concat(c.errors.length?c.errors:c.transfers.length?c.transfers.map(t=>`${personName(t.from)} → ${personName(t.to)} ${money(t.amount)}`):['송금 없음']).join('\n')}
$('#settleCopy').onclick=async()=>{try{await navigator.clipboard.writeText(shareText());showToast('정산 내용을 복사했어요.')}catch{showToast('복사할 수 없어요.')}};
$('#settleSave').onclick=()=>{const lines=shareText().split('\n'),canvas=document.createElement('canvas'),scale=2,w=760,h=100+lines.length*37;canvas.width=w*scale;canvas.height=h*scale;const ctx=canvas.getContext('2d');ctx.scale(scale,scale);const gradient=ctx.createLinearGradient(0,0,w,h);gradient.addColorStop(0,'#1b64da');gradient.addColorStop(1,'#3182f6');ctx.fillStyle=gradient;ctx.fillRect(0,0,w,h);ctx.fillStyle='#fff';ctx.font='700 21px sans-serif';lines.forEach((line,i)=>ctx.fillText(line,34,53+i*37));const a=document.createElement('a');a.href=canvas.toDataURL('image/png');a.download='점심-정산.png';a.click()};
renderAll();
